// Package assets embeds the popcorn icons (generated by tools/genicon).
package assets

import (
	"embed"
	"encoding/json"
	"io/fs"
	"runtime"
	"strings"
)

var (
	//go:embed tray.ico
	trayICO []byte
	//go:embed tray-paused.ico
	trayPausedICO []byte
	//go:embed tray.png
	trayPNG []byte
	//go:embed tray-paused.png
	trayPausedPNG []byte
	//go:embed tray-request.ico
	trayRequestICO []byte
	//go:embed tray-request.png
	trayRequestPNG []byte

	//go:embed icon-128.png
	Icon128 []byte
	// KnockSound plays for the sharer when someone asks to join; JoinSound
	// plays in viewers' browsers when another friend starts watching.
	//go:embed notification-sound.wav
	KnockSound []byte
	//go:embed join-sound.wav
	JoinSound []byte

	// Backgrounds of the viewer page's name and goodbye screens: full for
	// computers (with low, the same picture smaller, shown while it loads)
	// and mobile for phones held upright.
	//go:embed background-full.jpg
	BackgroundFull []byte
	//go:embed background-low.jpg
	BackgroundLow []byte
	//go:embed background-mobile.jpg
	BackgroundMobile []byte

	// Guide is the "How it works" page; {{ICON}} is replaced with Icon128.
	//go:embed guide.html
	Guide []byte
)

// ViewerFiles are served next to the viewer page.
func ViewerFiles() map[string][]byte {
	files := map[string][]byte{
		"join-sound.wav":        JoinSound,
		"background-full.jpg":   BackgroundFull,
		"background-low.jpg":    BackgroundLow,
		"background-mobile.jpg": BackgroundMobile,
	}
	throw, hit := Sounds()
	for _, name := range append(throw, hit...) {
		files[name], _ = sounds.ReadFile(name)
	}
	return files
}

// Emoji throw sounds: drop a throw-*.mp3 or hit-*.mp3 in this folder and
// rebuild, and it joins the draw; its odds are in sounds.json.
//
//go:embed throw-*.mp3 hit-*.mp3
var sounds embed.FS

//go:embed sounds.json
var soundOdds []byte

// SoundOdds is the weight of each throw and hit sound from sounds.json, with
// any sound file missing there at 1.
func SoundOdds() (throw, hit map[string]float64) {
	var odds struct{ Throw, Hit map[string]float64 }
	json.Unmarshal(soundOdds, &odds) // checked by the tests
	throwFiles, hitFiles := Sounds()
	return withAll(odds.Throw, throwFiles), withAll(odds.Hit, hitFiles)
}

func withAll(weights map[string]float64, files []string) map[string]float64 {
	if weights == nil {
		weights = map[string]float64{}
	}
	for _, f := range files {
		if _, ok := weights[f]; !ok {
			weights[f] = 1
		}
	}
	return weights
}

// Sounds lists the throw and hit sound files.
func Sounds() (throw, hit []string) {
	names, _ := fs.Glob(sounds, "*.mp3")
	for _, n := range names {
		if strings.HasPrefix(n, "throw-") {
			throw = append(throw, n)
		} else {
			hit = append(hit, n)
		}
	}
	return throw, hit
}

// Tray icon variants.
const (
	TrayNormal  = iota
	TrayPaused  // greyed out: not sharing, or paused
	TrayRequest // blue dot: someone is waiting to be let in
)

// Tray returns the tray icon in the format the OS tray expects (ICO on
// Windows, PNG elsewhere).
func Tray(variant int) []byte {
	ico := [...][]byte{trayICO, trayPausedICO, trayRequestICO}
	png := [...][]byte{trayPNG, trayPausedPNG, trayRequestPNG}
	if runtime.GOOS == "windows" {
		return ico[variant]
	}
	return png[variant]
}
